    backgroundEffect?: "static" | "slow-zoom-in" | "slow-zoom-out" | "ken-burns" | "drift" | "pulse" | "breathe" | "slow-tilt" | "camera-shake";
}

interface VideoSuppliedMedia {
    id: string;
    url: string;
    type: "image" | "video";
    description?: string;
    mimeType?: string;
    posterUrl?: string;
    focalPoint?: "center" | "top" | "bottom" | "left" | "right";
    treatment?: "subtle" | "cinematic" | "text-safe";
    role?: "product" | "proof" | "background" | "logo";
}

interface VideoTiming {
    beatStart?: number;
    beatEnd?: number;
    startTime?: number;
    endTime?: number;
    fixedDuration?: number;
    durationWeight?: number;
}

interface VideoWarning {
    code: VideoWarningCode;
    category: VideoWarningCategory;
    message: string;
    sceneId?: string;
    recoverable: boolean;
}

type MockVideoStreamPart = {
    type: "scene.add";
    placement?: "closer";
    scene: VideoScene;
} | {
    type: "plan.complete";
    finishReason?: "stop" | "length" | "content-filter" | "other";
} | {
    type: "mock.delay";
    durationMs: number;
} | {
    type: "mock.raw";
    text: string;
} | {
    type: "mock.error";
    message: string;
} | {
    type: "mock.wait-for-abort";
};

type SimulatedEventEnvelope<TType extends string, TData> = {
    protocolVersion: typeof VIDEO_PROTOCOL_VERSION;
    runId: string;
    sequence: number;
    eventId: string;
    type: TType;
    data: TData;
};

type SimulatedVideoEvent = SimulatedEventEnvelope<"response.start", {
    requestId: string;
    format: {
        orientation: VideoOrientation;
    };
    style: VideoStyle;
    meta?: Video["meta"];
    capabilities?: {
        templates?: string[];
        extensions?: string[];
    };
}> | SimulatedEventEnvelope<"audio.set", {
    audio: VideoAudio;
}> | SimulatedEventEnvelope<"scene.add", {
    scene: VideoScene;
    position: number;
}> | SimulatedEventEnvelope<"response.warning", {
    warning: VideoWarning;
}> | SimulatedEventEnvelope<"response.complete", {
    finishReason: VideoFinishReason;
    snapshot: Video;
    checksum: string;
}> | SimulatedEventEnvelope<"response.error", {
    error: {
        code: string;
        message: string;
        recoverable: boolean;
    };
    terminal: boolean;
    snapshot?: Video;
}> | SimulatedEventEnvelope<"response.abort", {
    reason: string;
    snapshot?: Video;
}> | SimulatedEventEnvelope<`data.${string}`, unknown>;
